  "ch7.cv.y": "Marginal cost ($/MWh)",
  "ch7.cv.day": "Price · 0:00 to 23:00",
  "ch7.cv.demand": "Demand",
  "plant.ren": "Wind & solar",
  "plant.nuc": "Nuclear",
  "plant.coal": "Coal",
